test('synthetic program-clock source expiry during otherwise allowed recording is rejected at actual information admission',async()=>{
  const f=setup({maximumProcessingMs:1000}),socket=await f.open(),logs=clone(tx.meta.logMessages) as string[];
  for(let i=0;i<logs.length;i++){if(!logs[i]!.startsWith('Program data: '))continue;const encoded=logs[i]!.slice(14),event=coder.events.decode(encoded);if(!event||!['BuyEvent','SellEvent'].includes(event.name))continue;const data=event.data as any;data.timestamp=new BN(Math.floor(f.now/1000)-29);logs[i]='Program data: '+Buffer.concat([Buffer.from(encoded,'base64').subarray(0,8),coder.types.encode(event.name,data)]).toString('base64');}
  f.delayNextRecord(500);f.notice(socket,{logs});assert.equal(f.trades.length,0);assert.ok(f.gaps.some(g=>/PROGRAM_CLOCK/.test(g.reason)));assert.equal(f.flow.snapshot(scope.mint)?.hasQualityLoss,true);await f.flow.stop();
});


